mapper.select:
-- Select one reclassification run with aggregated progress and outcome counts. SELECT
FROM announcement_source_reclassification_runs run
WHERE run.id = #{runId}

-- Select recent production reclassification runs for administrator monitoring. SELECT
FROM announcement_source_reclassification_runs run
ORDER BY run.created_at DESC, run.id DESC LIMIT #{limit}

-- Count only the conflict and failure outcomes belonging to the current run phase.
SELECT count(1)::integer
FROM announcement_source_reclassification_run_items item
WHERE item.run_id = #{runId}
  AND item.item_status_code IN

      #{statusCode}

mapper.update:
-- Remove only this run's applied evaluation from the current projection during rollback.
UPDATE announcement_source_classification_evaluations
SET is_current = FALSE
WHERE id = #{evaluationId}
  AND source_id = #{sourceId}
  AND is_current = TRUE

-- Restore the captured previous evaluation without deleting the appended evaluation history.
UPDATE announcement_source_classification_evaluations
SET is_current = TRUE
WHERE id = #{evaluationId}
  AND source_id = #{sourceId}
  AND is_current = FALSE

-- Restore only administrator target confirmations based on the previous evaluation.
UPDATE announcement_source_confirmed_target_categories
SET confirmation_status_code = 'CURRENT'
WHERE source_id = #{sourceId}
  AND based_on_evaluation_id = #{evaluationId}

-- Restore only administrator support confirmations based on the previous evaluation.
UPDATE announcement_source_confirmed_support_types
SET confirmation_status_code = 'CURRENT'
WHERE source_id = #{sourceId}
  AND based_on_evaluation_id = #{evaluationId}
